"""
MicroQueryRunner — fires micro-queries to LLM via injectable research_fn.
Enforces single-fact JSON responses. LLM = search engine only.
"""

import json
import time
from dataclasses import dataclass, field
from typing import Callable, Optional

from .micro_query_generator import MicroQuery

MICRO_FACT_PROMPT = """Answer this factual question with a SINGLE data point.
Format: {{"fact": "...", "value": "...", "confidence": 0.0-1.0, "source": "...", "date": "YYYY-MM-DD"}}

Question: {question}
Expected answer type: {expected_type}

Rules:
- ONE fact only. No reasoning, no explanation, no context.
- If you don't know, return {{"fact": null, "confidence": 0.0}}
- Include source URL or publication name if available."""

BATCH_SIZE = 5
BATCH_DELAY_S = 1.0


@dataclass
class MicroQueryResult:
    query: MicroQuery
    raw_response: str
    parsed_fact: Optional[dict] = None
    parse_success: bool = False

    def to_dict(self) -> dict:
        return {
            "query": self.query.to_dict(),
            "raw_response": self.raw_response[:500],
            "parsed_fact": self.parsed_fact,
            "parse_success": self.parse_success,
        }


@dataclass
class RunnerStats:
    queries_fired: int = 0
    responses_received: int = 0
    parse_successes: int = 0
    parse_failures: int = 0

    def to_dict(self) -> dict:
        return {
            "queries_fired": self.queries_fired,
            "responses_received": self.responses_received,
            "parse_successes": self.parse_successes,
            "parse_failures": self.parse_failures,
            "parse_success_rate": round(
                self.parse_successes / max(self.responses_received, 1), 3
            ),
        }


class MicroQueryRunner:
    def __init__(
        self,
        research_fn: Callable[[str], str],
        batch_size: int = BATCH_SIZE,
        batch_delay: float = BATCH_DELAY_S,
    ):
        self.research_fn = research_fn
        self.batch_size = batch_size
        self.batch_delay = batch_delay

    def run_batch(self, queries: list[MicroQuery]) -> tuple[list[MicroQueryResult], RunnerStats]:
        results: list[MicroQueryResult] = []
        stats = RunnerStats()

        for i in range(0, len(queries), self.batch_size):
            batch = queries[i : i + self.batch_size]

            if i > 0 and self.batch_delay > 0:
                time.sleep(self.batch_delay)

            for query in batch:
                result = self._run_single(query)
                results.append(result)
                stats.queries_fired += 1
                if result.raw_response:
                    stats.responses_received += 1
                if result.parse_success:
                    stats.parse_successes += 1
                else:
                    stats.parse_failures += 1

        return results, stats

    def _run_single(self, query: MicroQuery) -> MicroQueryResult:
        prompt = MICRO_FACT_PROMPT.format(
            question=query.text,
            expected_type=query.expected_type,
        )

        try:
            raw = self.research_fn(prompt)
        except Exception:
            return MicroQueryResult(query=query, raw_response="")

        parsed = self._parse_response(raw)
        if parsed:
            return MicroQueryResult(
                query=query,
                raw_response=raw,
                parsed_fact=parsed,
                parse_success=True,
            )

        # Fallback: try prose extraction
        parsed = self._parse_prose_fallback(raw, query)
        return MicroQueryResult(
            query=query,
            raw_response=raw,
            parsed_fact=parsed,
            parse_success=parsed is not None,
        )

    def _parse_response(self, raw: str) -> Optional[dict]:
        if not raw:
            return None
        text = raw.strip()
        # Find JSON in response
        start = text.find("{")
        end = text.rfind("}") + 1
        if start < 0 or end <= start:
            return None
        try:
            data = json.loads(text[start:end])
        except json.JSONDecodeError:
            return None

        if "fact" not in data:
            return None
        if data["fact"] is None:
            return None

        return {
            "fact": str(data["fact"]),
            "value": data.get("value"),
            "confidence": float(data.get("confidence", 0.5)),
            "source": data.get("source"),
            "date": data.get("date"),
        }

    def _parse_prose_fallback(self, raw: str, query: MicroQuery) -> Optional[dict]:
        if not raw or len(raw.strip()) < 10:
            return None
        text = raw.strip()
        if len(text) > 500:
            text = text[:500]

        confidence = self._score_prose_confidence(text)
        return {
            "fact": text,
            "value": self._extract_numeric_from_prose(text),
            "confidence": confidence,
            "source": "prose_extraction",
            "date": self._extract_date_from_prose(text),
        }

    def _score_prose_confidence(self, text: str) -> float:
        import re
        score = 0.35
        signals = [
            (re.compile(r'\$[\d,.]+[KMBkmb]?'), 0.12),
            (re.compile(r'\d{4}'), 0.08),
            (re.compile(r'https?://\S+'), 0.10),
            (re.compile(r'[A-Z][a-z]+\s+[A-Z][a-z]+'), 0.08),
            (re.compile(r'\d+%'), 0.10),
            (re.compile(r'(?:founded|launched|started|raised|acquired|sold|earned)'), 0.07),
            (re.compile(r'(?:million|billion|thousand|revenue|salary|fund|portfolio)'), 0.07),
            (re.compile(r'(?:CEO|CTO|GP|LP|partner|director|founder|manager)', re.IGNORECASE), 0.05),
        ]
        for pattern, boost in signals:
            if pattern.search(text):
                score += boost
        return min(0.85, score)

    def _extract_numeric_from_prose(self, text: str) -> Optional[float]:
        import re
        match = re.search(r'\$\s*([\d,.]+)\s*([KMBkmb]?)', text)
        if match:
            num_str = match.group(1).replace(",", "")
            try:
                val = float(num_str)
                multiplier = {"k": 1e3, "m": 1e6, "b": 1e9}.get(match.group(2).lower(), 1)
                return val * multiplier
            except ValueError:
                pass
        return None

    def _extract_date_from_prose(self, text: str) -> Optional[str]:
        import re
        match = re.search(r'(20[12]\d)', text)
        return f"{match.group(1)}-01-01" if match else None

"""
WebResearchBridge — creates real research_fn for MicroQueryRunner.
Uses DuckDuckGo for zero-API-key web search.
Falls back to requests-based scraping if DDG fails.
"""

import json
import time
import warnings
from typing import Optional

warnings.filterwarnings("ignore", message=".*renamed.*ddgs.*")

_LAST_CALL_TIME = 0.0
_MIN_DELAY_S = 1.5


def _rate_limit():
    global _LAST_CALL_TIME
    now = time.time()
    elapsed = now - _LAST_CALL_TIME
    if elapsed < _MIN_DELAY_S:
        time.sleep(_MIN_DELAY_S - elapsed)
    _LAST_CALL_TIME = time.time()


def ddg_research(prompt: str) -> str:
    """Research function using DuckDuckGo. Returns raw text for MicroQueryRunner to parse."""
    question = _extract_question(prompt)
    if not question:
        return ""

    _rate_limit()

    try:
        import warnings
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            try:
                from ddgs import DDGS
            except ImportError:
                from duckduckgo_search import DDGS
            with DDGS() as ddgs:
                results = list(ddgs.text(question, max_results=5))
    except Exception:
        results = []

    if not results:
        return _fallback_search(question)

    snippets = []
    for r in results[:5]:
        title = r.get("title", "")
        body = r.get("body", "")
        href = r.get("href", "")
        snippets.append(f"{title}: {body} (source: {href})")

    combined = "\n".join(snippets)

    fact = _extract_fact_from_snippets(combined, question)
    return fact


def _extract_question(prompt: str) -> str:
    """Extract the actual question from the micro-query prompt template."""
    lines = prompt.strip().split("\n")
    for line in lines:
        if line.startswith("Question:"):
            return line.replace("Question:", "").strip()
    for line in lines:
        if "?" in line and not line.startswith("Format:") and not line.startswith("Rules:"):
            return line.strip()
    return prompt[:200]


def _extract_fact_from_snippets(text: str, question: str) -> str:
    """Convert search snippets into structured fact JSON for MicroQueryRunner.
    Picks the MOST RELEVANT snippet to the question, not just the first one.
    Applies relevance penalty when snippet doesn't answer the question.
    """
    import re

    snippets = text.split("\n")
    best_snippet, best_relevance = _pick_best_snippet(snippets, question)

    numbers = re.findall(r'[\d,.]+%|[$€£]\s*[\d,.]+[KMBkmb]?|\d{1,3}(?:,\d{3})*(?:\.\d+)?', best_snippet)
    first_url = ""
    url_match = re.search(r'source:\s*(https?://[^\s\)]+)', best_snippet)
    if not url_match:
        url_match = re.search(r'source:\s*(https?://[^\s\)]+)', text)
    if url_match:
        first_url = url_match.group(1)

    value = numbers[0] if numbers else None
    confidence = _score_confidence(best_snippet, first_url, numbers)
    # Relevance penalty only for poor matches (<0.6), not for good ones
    if best_relevance < 0.6:
        confidence = round(confidence * (0.5 + best_relevance), 2)
    else:
        confidence = round(confidence, 2)

    fact_json = {
        "fact": best_snippet[:200],
        "value": value,
        "confidence": confidence,
        "source": first_url or "duckduckgo_search",
        "date": None,
    }

    return json.dumps(fact_json, ensure_ascii=False)


def _pick_best_snippet(snippets: list[str], question: str) -> tuple[str, float]:
    """Score each snippet by keyword overlap with question. Return best + relevance score."""
    q_terms = _extract_keywords(question)
    if not q_terms or not snippets:
        combined = "\n".join(snippets)[:300]
        return combined, 0.5

    best_text = snippets[0] if snippets else ""
    best_score = 0.0

    for snippet in snippets:
        if not snippet.strip():
            continue
        s_lower = snippet.lower()
        hits = sum(1 for t in q_terms if t in s_lower)
        score = hits / len(q_terms)
        if score > best_score:
            best_score = score
            best_text = snippet

    relevance = min(1.0, 0.5 + best_score * 0.5) if best_score > 0 else 0.4
    return best_text[:300], relevance


def _extract_keywords(text: str) -> list[str]:
    """Extract meaningful keywords from a question, ignoring stop words."""
    stop = {
        "what", "how", "is", "the", "a", "an", "in", "of", "for", "to", "and",
        "or", "are", "was", "were", "be", "been", "do", "does", "did", "will",
        "can", "could", "should", "would", "may", "might", "much", "many",
        "typical", "common",
    }
    import re
    words = re.findall(r'[a-zA-Z]{3,}', text.lower())
    return [w for w in words if w not in stop]


_AUTHORITY_DOMAINS = {
    ".gov": 0.15, ".edu": 0.12, "who.int": 0.12, "worldbank.org": 0.12,
    "statista.com": 0.10, "crunchbase.com": 0.08, "pitchbook.com": 0.08,
    "dealstreetasia.com": 0.08, "techcrunch.com": 0.06, "reuters.com": 0.08,
    "bloomberg.com": 0.08, "wikipedia.org": 0.05, "linkedin.com": 0.04,
}


def _score_confidence(text: str, url: str, numbers: list) -> float:
    score = 0.35
    if numbers:
        score += 0.15
    if len(numbers) >= 3:
        score += 0.10
    url_lower = url.lower()
    for domain, boost in _AUTHORITY_DOMAINS.items():
        if domain in url_lower:
            score += boost
            break
    if any(w in text.lower() for w in ["according to", "reported", "data shows", "survey", "study"]):
        score += 0.05
    import re
    if re.search(r'\b20[12]\d\b', text):
        score += 0.05
    return min(0.90, round(score, 2))


def _fallback_search(question: str) -> str:
    """Fallback: use requests to hit DuckDuckGo HTML directly."""
    import requests
    try:
        resp = requests.get(
            "https://html.duckduckgo.com/html/",
            params={"q": question},
            headers={"User-Agent": "Mozilla/5.0"},
            timeout=10,
        )
        if resp.status_code == 200:
            text = resp.text[:2000]
            import re
            snippets = re.findall(r'class="result__snippet">(.*?)</a>', text)
            if snippets:
                combined = " ".join(s[:100] for s in snippets[:3])
                return json.dumps({
                    "fact": combined[:200],
                    "value": None,
                    "confidence": 0.35,
                    "source": "duckduckgo_html_fallback",
                    "date": None,
                }, ensure_ascii=False)
    except Exception:
        pass
    return ""


def create_research_fn(delay_s: float = 1.5) -> callable:
    """Factory: creates a rate-limited research function."""
    global _MIN_DELAY_S
    _MIN_DELAY_S = delay_s
    return ddg_research

"""
StrategicReasoner — LLM reasoning layer AFTER SynthesisEngine scores facts.
SynthesisEngine stays LOCAL-ONLY. This module is where LLM actually THINKS.
Max 5 LLM calls per brainstorm, every claim references input facts.

Call order:
  1. Synthesis      — mechanism extraction
  2. Founder Map    — map founder position to opportunity nodes
  3. Strategy       — asymmetric play with founder constraints
  4. Compound Asset — permanent asset blueprint
  5. Verdict        — GO/KILL with field reasoning (Munger inversion)
"""

import json
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Optional


@dataclass
class StrategicInsight:
    causal_chain: str
    contradictions: list[dict] = field(default_factory=list)
    inferred_gaps: list[dict] = field(default_factory=list)
    asymmetric_play: str = ""
    compound_trap: str = ""
    kill_go_reasoning: str = ""
    verdict: str = ""
    kill_conditions: list[dict] = field(default_factory=list)
    proceed_conditions: list[dict] = field(default_factory=list)
    fact_references: list[str] = field(default_factory=list)
    llm_calls_made: int = 0
    total_latency_ms: int = 0
    # New fields (calls 2 + 4)
    founder_constraint_map: dict = field(default_factory=dict)
    compound_asset_blueprint: dict = field(default_factory=dict)
    side_doors: list[str] = field(default_factory=list)
    mental_models_applied: list[str] = field(default_factory=list)
    local_verdict: dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        d = {
            "causal_chain": self.causal_chain,
            "contradictions": self.contradictions,
            "inferred_gaps": self.inferred_gaps,
            "asymmetric_play": self.asymmetric_play,
            "compound_trap": self.compound_trap,
            "kill_go_reasoning": self.kill_go_reasoning,
            "verdict": self.verdict,
            "kill_conditions": self.kill_conditions,
            "proceed_conditions": self.proceed_conditions,
            "fact_references": self.fact_references,
            "llm_calls_made": self.llm_calls_made,
            "total_latency_ms": self.total_latency_ms,
            "founder_constraint_map": self.founder_constraint_map,
            "compound_asset_blueprint": self.compound_asset_blueprint,
            "side_doors": self.side_doors,
            "mental_models_applied": self.mental_models_applied,
        }
        if self.local_verdict:
            d["local_verdict"] = self.local_verdict
        return d


def _empty_insight(reason: str = "degraded") -> StrategicInsight:
    return StrategicInsight(causal_chain=f"[{reason}]", llm_calls_made=0)


class StrategicReasoner:
    def __init__(self, max_calls: int = 5, llm_fn: Optional[Callable] = None):
        self.max_calls = max_calls
        self._llm_fn = llm_fn
        self._calls_made = 0

    @staticmethod
    def _compress_technique_results(tr: dict) -> str:
        if not tr or tr.get("error"):
            return ""
        lines = []
        consensus = tr.get("consensus", "UNKNOWN")
        go = tr.get("techniques_agreeing_go", 0)
        kill = tr.get("techniques_agreeing_kill", 0)
        lines.append(f"15-technique consensus: {consensus} (GO={go} KILL={kill})")
        results = tr.get("results", {})
        for tid, tres in results.items():
            if not isinstance(tres, dict):
                continue
            v = tres.get("verdict", "")
            chain = tres.get("reasoning_chain", [])
            reason_text = chain[0][:100] if chain else ""
            if consensus == "GO" and v in ("KILL", "NEEDS_DATA"):
                lines.append(f"CONTRARIAN {tid}: {v} — {reason_text}")
            elif consensus == "KILL" and v == "GO":
                lines.append(f"CONTRARIAN {tid}: GO — {reason_text}")
        if tr.get("fragile_block"):
            lines.append("FRAGILE revenue detected — durability concern")
        if tr.get("staircase_override"):
            lines.append("Staircase override: capital constraint has viable growth path")
        return "\n".join(lines[:15])

    def reason(
        self,
        facts: list,
        dim_scores: dict,
        query_context: dict,
        founder_context: dict,
        mental_models_context: str = "",
        technique_context: str = "",
        local_verdict_context: str = "",
    ) -> StrategicInsight:
        if not facts:
            return _empty_insight("no_facts")

        self._calls_made = 0
        start = time.time()
        fact_context = self._format_facts(facts, dim_scores)
        fact_refs = [getattr(f, "fact", str(f))[:80] for f in facts[:20]]

        synthesis_data: dict = {"causal_chain": "[error]"}
        founder_map_data: dict = {}
        strategy_data: dict = {}
        compound_data: dict = {}
        verdict_data: dict = {}

        # --- Call 1: Synthesis ---
        try:
            synthesis = self._call_llm(
                self._build_synthesis_prompt(fact_context, query_context, technique_context)
            )
            synthesis_data = self._parse_json(synthesis, {
                "causal_chain": "Unknown mechanism",
                "contradictions": [],
                "inferred_gaps": [],
            })
        except Exception:
            return StrategicInsight(
                causal_chain=synthesis_data.get("causal_chain", "[error]"),
                fact_references=fact_refs,
                llm_calls_made=self._calls_made,
                total_latency_ms=int((time.time() - start) * 1000),
            )

        # --- Call 2: Founder Constraint Map ---
        try:
            founder_map = self._call_llm(
                self._build_founder_map_prompt(synthesis_data, founder_context, query_context, technique_context)
            )
            founder_map_data = self._parse_json(founder_map, {
                "insertion_node": "unknown",
                "advantages": [],
                "biggest_constraint": "unknown",
                "workaround": "none identified",
            })
        except Exception:
            # Graceful degradation — continue without founder map
            founder_map_data = {}

        # --- Call 3: Strategy ---
        try:
            strategy = self._call_llm(
                self._build_strategy_prompt(
                    synthesis_data, founder_map_data, founder_context, query_context,
                    mental_models_context, technique_context,
                )
            )
            strategy_data = self._parse_json(strategy, {
                "asymmetric_play": "None identified",
                "compound_trap": "None identified",
                "side_doors": [],
                "mental_models": [],
            })
        except Exception:
            strategy_data = {}

        # --- Call 4: Compound Asset Design ---
        try:
            compound = self._call_llm(
                self._build_compound_prompt(strategy_data, query_context, technique_context)
            )
            compound_data = self._parse_json(compound, {
                "asset_name": "unknown",
                "how_it_compounds": "unknown",
                "moat_at_12_months": "unknown",
                "self_reinforcing_at": "unknown",
                "redesign_needed": False,
            })
        except Exception:
            compound_data = {}

        # --- Call 5: Verdict ---
        try:
            verdict = self._call_llm(
                self._build_verdict_prompt(
                    synthesis_data, founder_map_data, strategy_data, compound_data,
                    query_context, technique_context, local_verdict_context,
                )
            )
            verdict_data = self._parse_json(verdict, {
                "verdict": "UNCERTAIN",
                "kill_conditions": [],
                "proceed_conditions": [],
                "reasoning": "Insufficient data for mechanistic verdict",
                "mental_models_applied": [],
            })
        except Exception:
            verdict_data = {
                "verdict": "UNCERTAIN",
                "kill_conditions": [],
                "proceed_conditions": [],
                "reasoning": "Verdict call failed — partial analysis only",
                "mental_models_applied": [],
            }

        side_doors: list[str] = strategy_data.get("side_doors", [])
        if isinstance(side_doors, str):
            side_doors = [side_doors]

        mental_models: list[str] = verdict_data.get("mental_models_applied", [])
        if isinstance(mental_models, str):
            mental_models = [mental_models]

        return StrategicInsight(
            causal_chain=synthesis_data.get("causal_chain", ""),
            contradictions=synthesis_data.get("contradictions", []),
            inferred_gaps=synthesis_data.get("inferred_gaps", []),
            asymmetric_play=strategy_data.get("asymmetric_play", ""),
            compound_trap=strategy_data.get("compound_trap", ""),
            kill_go_reasoning=verdict_data.get("reasoning", ""),
            verdict=verdict_data.get("verdict", "UNCERTAIN"),
            kill_conditions=verdict_data.get("kill_conditions", []),
            proceed_conditions=verdict_data.get("proceed_conditions", []),
            fact_references=fact_refs,
            llm_calls_made=self._calls_made,
            total_latency_ms=int((time.time() - start) * 1000),
            founder_constraint_map=founder_map_data,
            compound_asset_blueprint=compound_data,
            side_doors=side_doors,
            mental_models_applied=mental_models,
        )

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------

    def _call_llm(self, prompt: str) -> str:
        if self._calls_made >= self.max_calls:
            raise RuntimeError(f"LLM call budget exhausted ({self.max_calls})")

        self._calls_made += 1

        if self._llm_fn:
            result = self._llm_fn(prompt, max_tokens=2048, temperature=0.3)
        else:
            from ...llm.factory import complete_with_fallback
            result = complete_with_fallback(prompt, max_tokens=2048, temperature=0.3)

        if result is None or not hasattr(result, 'content'):
            raise RuntimeError("LLM returned invalid response object")
        return result.content or ""

    def _parse_json(self, text: str, defaults: dict) -> dict:
        text = text.strip()
        start = text.find("{")
        end = text.rfind("}") + 1
        if start >= 0 and end > start:
            try:
                return json.loads(text[start:end])
            except json.JSONDecodeError:
                pass
        return {**defaults, "_raw": text[:500]}

    def _format_facts(self, facts: list, dim_scores: dict) -> str:
        by_dim: dict[str, list[str]] = {}
        for f in facts:
            dim = getattr(f, "dimension", "unknown")
            fact_text = getattr(f, "fact", str(f))
            zone = getattr(f, "zone_tag", "?")
            by_dim.setdefault(dim, []).append(f"[{zone}] {fact_text[:150]}")

        lines = []
        for dim, dim_facts in by_dim.items():
            score_obj = dim_scores.get(dim)
            score_val = getattr(score_obj, "score", 0) if score_obj else 0
            lines.append(f"\n## {dim} (score: {score_val:.2f})")
            for ff in dim_facts[:5]:
                lines.append(f"  - {ff}")
        return "\n".join(lines)

    # ------------------------------------------------------------------
    # Prompts — cunning operator voice, not analyst voice
    # ------------------------------------------------------------------

    def _build_synthesis_prompt(self, fact_context: str, query_context: dict, technique_context: str = "") -> str:
        query = query_context.get("original_query", query_context.get("query", ""))
        technique_block = f"\n\n## 15-Technique Pre-Analysis\n{technique_context}" if technique_context else ""
        return f"""You've operated across 1,000 deals in Southeast Asia. You've watched smart people fail because they copied visible paths instead of understanding invisible mechanisms. You think in bottleneck nodes, information asymmetry, and compound assets — not "market analysis" or "competitive landscape."

You're given verified facts across multiple dimensions about: "{query}"

FACTS:{fact_context}{technique_block}

Your job is NOT to summarize. Your job is to find the mechanism.

